def migrate(source):
    code = t.boundary.executable_code(source)
    if not re.search(r'\bclass\s+PremiumFeature\d+\s+extends\s+GovernedConsumerWidget\b', code):
        return source, 0
    for package in ('flutter/material.dart', 'primecare_ui/primecare_ui.dart'):
        pattern = r"\bimport\s+(['\"])package:" + re.escape(package) + r'\1\s*;'
        if not any(code[m.start():].startswith('import') for m in re.finditer(pattern, source)):
            return source, 0
    if re.search(r'\bpart\b|\b(?:class|typedef|mixin|enum|extension)\s+(?:Color|Colors|PrimeTelemetryRow|PrimeIcon|PrimeText)\b', code):
        return source, 0
    if re.search(r'\b(?:Color|Colors|PrimeTelemetryRow|PrimeIcon|PrimeText)\s*=', code):
        return source, 0
    if re.search(r'\b(?:Widget|dynamic|Object|Function)\s+PrimeTelemetryRow\s*\(', code):
        return source, 0
    if source.count(OLD) != 1:
        return source, 0
    offset = source.index(OLD)
    if not code[offset:].startswith('class _TelemetryPanel extends'):
        return source, 0
    return source[:offset] + NEW + source[offset+len(OLD):], 6


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument('--offset', type=int, default=0)
    parser.add_argument('--limit', type=int, default=100)
    parser.add_argument('--apply', action='store_true')
    args = parser.parse_args()
    if args.offset < 0 or args.limit < 1:
        parser.error('offset must be nonnegative and limit positive')
    root = args.root.resolve()
    files = []
    for path in sorted((root/'packages/primecare_ui/lib/src/features/generated_screens').glob('premium_feature_*.dart'))[args.offset:args.offset+args.limit]:
        if path.is_symlink() or not path.resolve().is_relative_to(root):
            continue
        updated, count = migrate(path.read_text())
        if count:
            if args.apply:
                path.write_text(updated)
            files.append(path.relative_to(root).as_posix())
    print(json.dumps({'applied': args.apply, 'rows': len(files)*6, 'files': files}, indent=2))


if __name__ == '__main__':
    main()
